package com.example.campsitelotterysystem.ui

import org.junit.Assert.assertEquals
import org.junit.Assert.assertNull
import org.junit.Test

/**
 * This Test was generated by AI - Claude 2026-11-05 - "write test cases to validate errors"
 * Tests for validateProfile. It is a plain function, so no emulator is needed.
 */
class ProfileValidationTest {

    @Test
    fun validProfileHasNoError() {
        assertNull(validateProfile("Avery", "avery@example.com", "780-555-1234"))
    }

    @Test
    fun emailAndPhoneAreOptional() {
        assertNull(validateProfile("Avery", "", ""))
    }

    @Test
    fun blankNameIsAnError() {
        assertEquals("Name is required.", validateProfile("   ", "", ""))
    }

    @Test
    fun badEmailIsAnError() {
        assertEquals("Email is not valid.", validateProfile("Avery", "not-an-email", ""))
    }

    @Test
    fun shortPhoneIsAnError() {
        assertEquals(
            "Phone number needs at least 10 digits.",
            validateProfile("Avery", "", "12345")
        )
    }

    @Test
    fun phoneWithDashesAndSpacesCountsOnlyDigits() {
        assertNull(validateProfile("Avery", "", "(780) 555-1234"))
    }
}